        // 速度合法（50 米/秒）但命中禁飞区：保存 BLOCKED 结论
        MutationResponse resp = service.submitTimedReview(
                timedReq("t-blk", 1, 1L, List.of(at(0), at(2)), "req-" + rid("timed")));
        TimedReviewResultDto dto = timedData(resp);
